  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Commands, Travel and Community$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. Psalm 121:8 says, The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.\n\nPart 1: Explain how to form formal commands and write the usted and ustedes commands for six verbs, including two irregular ones.\nPart 2: Explain how to form affirmative and negative tú commands and write both forms for six verbs, including three irregular ones.\nPart 3: Write a Spanish dialogue of at least ten lines in which a visitor asks for directions to your church, using travel words and formal commands.\nPart 4: Write a Spanish dialogue of at least eight lines at a pharmacy or clinic using symptom words and one emergency phrase.\nPart 5: Explain when a volunteer should call a professional or a trained interpreter, and why.\nPart 6: Explain how James 5:14 and Matthew 25:40 guide the church's care for people in need.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 10 points. Part 6: 10 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Commands, Travel and Community$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Giving Good Directions$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time someone helped you find your way or you helped someone else, (2) shares at least three Spanish commands or directions from this unit, and (3) connects your answer to Psalm 121:8 or Proverbs 3:5. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do we use a formal command with an elder and an informal command with a friend?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Giving Good Directions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Formal Commands with Usted and Ustedes$j$, $j${"questions": [{"q": "The usted command of hablar is:", "options": ["Hablar", "Habla", "Hablas", "Hable"]}, {"q": "The usted command of venir is:", "options": ["Venie", "Vienga", "Viene", "Venga"]}, {"q": "Siéntese means:", "options": ["I sit", "Sit them", "Sit down", "Do not sit"]}, {"q": "The usted command of ser is:", "options": ["Sé", "Es", "Sea", "Sera"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Formal Commands with Usted and Ustedes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,2,2}'::int[], array[$j$Ar verbs take e in the formal command.$j$,$j$The yo form vengo gives venga.$j$,$j$Sentarse in an affirmative formal command.$j$,$j$Sea is irregular.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Formal Commands with Usted and Ustedes$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Informal Commands with Tú$j$, $j${"questions": [{"q": "The affirmative tú command of hablar is:", "options": ["Habla", "Hable", "Hables", "Hablas"]}, {"q": "The affirmative tú command of hacer is:", "options": ["Hagas", "Hazo", "Hace", "Haz"]}, {"q": "The negative tú command of comer is:", "options": ["No comes", "No comas", "No coma", "No come"]}, {"q": "The negative tú command of ir is:", "options": ["No vaya", "No vayas", "No vas", "No ve"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Informal Commands with Tú$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,1}'::int[], array[$j$It matches the él form.$j$,$j$Hacer is irregular and becomes haz.$j$,$j$Negative tú commands use the opposite vowel plus s.$j$,$j$Ir is irregular in the negative.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Informal Commands with Tú$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Travel, Transportation and Directions$j$, $j${"questions": [{"q": "Doble a la izquierda means:", "options": ["Turn left", "Stop", "Turn right", "Go straight"]}, {"q": "El boleto is:", "options": ["The passport", "The bus", "The ticket", "The suitcase"]}, {"q": "Quisiera comprar un boleto is:", "options": ["A question about time", "A polite request", "A command", "A past event"]}, {"q": "Está enfrente de la iglesia means:", "options": ["It is inside the church", "It is across from the church", "It is far from the church", "It was the church"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Travel, Transportation and Directions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,1}'::int[], array[$j$Izquierda means left.$j$,$j$Boleto means ticket.$j$,$j$Quisiera makes a request polite.$j$,$j$Enfrente de means across from or opposite.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Travel, Transportation and Directions$j$ on conflict (item_id) do nothing;
